"""TableSync prototype: weekly supplier ordering + par-level inventory for a small restaurant."""
from dataclasses import dataclass, field

@dataclass
class Item:
    name: str
    unit: str
    par: float          # target on-hand quantity
    on_hand: float
    supplier: str
    unit_cost: float

@dataclass
class Inventory:
    items: list = field(default_factory=list)

    def count(self, name, qty):
        for it in self.items:
            if it.name == name:
                it.on_hand = qty
                return
        raise KeyError(name)

    def order_list(self):
        """Return {supplier: [(item, qty, cost)]} needed to bring each item back to par."""
        orders = {}
        for it in self.items:
            need = max(0.0, it.par - it.on_hand)
            if need > 0:
                cost = round(need * it.unit_cost, 2)
                orders.setdefault(it.supplier, []).append((it.name, need, cost))
        return orders

    def summary(self):
        lines = []
        for sup, rows in sorted(self.order_list().items()):
            total = sum(c for _, _, c in rows)
            lines.append(f"{sup}: ${total:.2f}")
            for name, qty, cost in rows:
                lines.append(f"  - {name}: {qty:g} (${cost:.2f})")
        return "\n".join(lines) or "Nothing to order."

if __name__ == "__main__":
    inv = Inventory([
        Item("Chicken thighs", "lb", 30, 12, "Valley Meats", 2.10),
        Item("Rice", "lb", 50, 35, "Asian Grocer", 0.80),
        Item("Tortillas", "pack", 20, 6, "Valley Meats", 3.00),
        Item("Limes", "each", 40, 40, "Produce Co", 0.25),
    ])
    print(inv.summary())
